-- ============================================================================
-- seeds/warcastle-tables-11-13.sql
--
-- The real set-ups for WarCastle tables 11 to 13 (Grant's sketches, 4 Nov),
-- with their names and descriptions (Grant, 4 Nov), in the scenario builder's format, with no deployment (the attack sets
-- that) and no objective markers:
--   11 The Fortenhaf Fields: two wheat fields, each with a building at its west
--     end, two buildings in the north-east and a hill in the south-east
--     corner, running off the table's edges.
--   12 The Chernigov Plains: two buildings in the north-west, three hills and a
--     wood.
--   13 Möllers Field: an eerie green glow over the table; the warpstone
--     crash, a crater with the Shard of Morr (special feature) lying west to
--     east in it under its smoke; four ruins and a wheat field.
-- Terrain can still be moved in Set up > Tables.
--
-- Run in the Supabase SQL editor, after seeds/warcastle.sql. It finds the
-- real event by its WarCastle template, so a renamed event is fine. It sets
-- tables 11 to 13 and leaves the others as they are. Then re-run
-- seeds/warcastle-test.sql to copy them into WarCastle (test).
-- Safe to run again: the scenarios keep their ids.
-- ============================================================================

do $do$
declare
  v_campaign campaigns%rowtype;
  v_tables   jsonb := '{}'::jsonb;
  r          jsonb;
begin
  -- the real WarCastle event, by its template (it can be renamed), not the test copy
  if (select count(*) from campaigns where settings ->> 'template' = 'warcastle' and name <> 'WarCastle (test)') > 1 then
    raise exception 'More than one WarCastle event: %', (select string_agg(name, ', ') from campaigns where settings ->> 'template' = 'warcastle' and name <> 'WarCastle (test)');
  end if;
  select * into v_campaign from campaigns where settings ->> 'template' = 'warcastle' and name <> 'WarCastle (test)';
  if not found then raise exception 'No WarCastle event found: run seeds/warcastle.sql first.'; end if;

